"""Main RAG pipeline -- ingest, retrieve, generate."""

from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from rag_qa.config import RAGConfig
from rag_qa.chunker import TextChunker, Chunk
from rag_qa.embedder import Embedder
from rag_qa.retriever import Retriever, RetrievalResult


@dataclass
class Answer:
    """An answer generated by the RAG pipeline."""

    text: str
    sources: list[dict[str, Any]] = field(default_factory=list)
    context_chunks: list[str] = field(default_factory=list)
    confidence: float = 0.0

    def to_dict(self) -> dict[str, Any]:
        return {
            "answer": self.text,
            "sources": self.sources,
            "num_chunks_used": len(self.context_chunks),
            "confidence": round(self.confidence, 4),
        }


class RAGPipeline:
    """Complete Retrieval-Augmented Generation pipeline.

    Orchestrates document ingestion, embedding, retrieval,
    and answer generation.

    Example:
        >>> rag = RAGPipeline()
        >>> rag.ingest("./docs/")
        >>> answer = rag.query("What is the main idea?")
        >>> print(answer.text)
    """

    def __init__(self, config: RAGConfig | None = None):
        """Initialize the RAG pipeline.

        Args:
            config: Pipeline configuration. Uses defaults if None.
        """
        self.config = config or RAGConfig()
        self.chunker = TextChunker(
            chunk_size=self.config.chunk_size,
            chunk_overlap=self.config.chunk_overlap,
        )
        self.embedder = Embedder(model_name=self.config.embedding_model)
        self.retriever = Retriever(embedding_dim=self.embedder.dim)
        self._ingested_sources: list[str] = []

    def ingest(self, path: str | Path) -> int:
        """Ingest documents from a file or directory.

        Args:
            path: Path to a file or directory.

        Returns:
            Number of chunks indexed.
        """
        path = Path(path)

        if path.is_file():
            chunks = self.chunker.chunk_file(path)
        elif path.is_dir():
            chunks = self.chunker.chunk_directory(
                path,
                extensions=self.config.supported_extensions,
            )
        else:
            raise FileNotFoundError(f"Path not found: {path}")

        if not chunks:
            return 0

        embeddings = self.embedder.embed_chunks(chunks)
        self.retriever.add(chunks, embeddings)
        self._ingested_sources.append(str(path))

        return len(chunks)

    def ingest_text(self, text: str, source: str = "direct_input") -> int:
        """Ingest raw text directly.

        Args:
            text: Text content to index.
            source: Source identifier.

        Returns:
            Number of chunks indexed.
        """
        chunks = self.chunker.chunk_text(text, source=source)
        if not chunks:
            return 0

        embeddings = self.embedder.embed_chunks(chunks)
        self.retriever.add(chunks, embeddings)
        return len(chunks)

    def query(self, question: str) -> Answer:
        """Ask a question and get an answer from the indexed documents.

        Args:
            question: Natural language question.

        Returns:
            Answer object with text, sources, and confidence.
        """
        if self.retriever.size == 0:
            return Answer(
                text="No documents have been indexed. Please ingest documents first.",
                confidence=0.0,
            )

        # Retrieve relevant chunks
        query_embedding = self.embedder.embed_query(question)
        results = self.retriever.search(
            query_embedding,
            top_k=self.config.top_k,
            threshold=self.config.similarity_threshold,
        )

        if not results:
            return Answer(
                text="I could not find relevant information in the indexed documents.",
                confidence=0.0,
            )

        # Build context and generate answer
        context = self._build_context(results)
        answer_text = self._generate_answer(question, context)

        sources = [
            {
                "source": r.chunk.source,
                "chunk_id": r.chunk.chunk_id,
                "score": round(r.score, 4),
                "excerpt": r.chunk.text[:150] + "...",
            }
            for r in results
        ]

        avg_score = sum(r.score for r in results) / len(results)

        return Answer(
            text=answer_text,
            sources=sources,
            context_chunks=[r.chunk.text for r in results],
            confidence=avg_score,
        )

    def retrieve(self, query: str, top_k: int | None = None) -> list[RetrievalResult]:
        """Retrieve relevant chunks without generating an answer.

        Useful for debugging or building custom pipelines.

        Args:
            query: Search query.
            top_k: Number of results (overrides config).

        Returns:
            List of RetrievalResult objects.
        """
        query_embedding = self.embedder.embed_query(query)
        return self.retriever.search(
            query_embedding,
            top_k=top_k or self.config.top_k,
            threshold=self.config.similarity_threshold,
        )

    def save_index(self, path: str | Path | None = None) -> None:
        """Save the index to disk."""
        save_path = Path(path or self.config.index_path)
        self.retriever.save(save_path)

    def load_index(self, path: str | Path | None = None) -> None:
        """Load a previously saved index."""
        load_path = Path(path or self.config.index_path)
        self.retriever.load(load_path)

    def stats(self) -> dict[str, Any]:
        """Get index statistics."""
        return {
            "total_chunks": self.retriever.size,
            "embedding_dim": self.embedder.dim,
            "sources": self._ingested_sources,
            "config": {
                "chunk_size": self.config.chunk_size,
                "top_k": self.config.top_k,
                "model": self.config.embedding_model,
            },
        }

    def _build_context(self, results: list[RetrievalResult]) -> str:
        """Build LLM context from retrieved chunks."""
        parts = []
        for i, result in enumerate(results, 1):
            parts.append(
                f"[Source {i}: {result.chunk.source}]\n{result.chunk.text}"
            )
        return "\n\n---\n\n".join(parts)

    @staticmethod
    def _generate_answer(question: str, context: str) -> str:
        """Generate answer from context.

        This is a template-based approach. For production, integrate
        with a full LLM (GPT, Claude, Llama, etc.) via API or local model.
        """
        # Simple extractive answer: return most relevant context
        # In production, this would call an LLM with a prompt like:
        # f"Based on the following context, answer the question.\n\n"
        # f"Context:\n{context}\n\nQuestion: {question}\n\nAnswer:"

        return (
            f"Based on the indexed documents:\n\n"
            f"{context[:1500]}\n\n"
            f"(To enable LLM-generated answers, configure an LLM backend "
            f"via the generator module.)"
        )
